rule.example:

import java.util.Comparator
data class Person(val name: String)
class PersonSorter {
    fun sortBad(people: List<Person>) = people.sortedWith(Comparator.comparing { it.name }) // bad: recreated per call
    companion object {
        val BY_NAME = Comparator.comparing(Person::name) // ok: created once
    }
    fun sortGood(people: List<Person>) = people.sortedWith(BY_NAME)
}

